    "cover": {
      "headline": "Singapore",
      "narration": "Singapore, 20–22 Nov 2026: 3 days, 2 travellers, and one puffin narrating from a comfortably chilly distance."
    },
    "critters": {
      "narration": "The crew logged 2 forms and met 1 new local critter. Consider that a very successful diplomatic mission."
    },
    "route": {
      "narration": "They roamed about 22.1 km through Marina Bay, Tiong Bahru, and Sentosa.",
      "line": "Longest leg: Tiong Bahru to Sentosa, 9.6 km in 20 minutes, with no driver on record."
    },
    "awards": {
      "narration": "Two travellers, two awards. I checked the numbers twice, then gave up and cheered."
    },
    "receipt": {
      "narration": "SGD 1,240 in total, or SGD 620 each, across 14 expenses and 8 meals.",
      "line": "No planned total, so we shall call it a perfectly balanced budget."
    },
    "stamp": {
      "narration": "Stamped and signed: Singapore goes on the pass, right between the hot springs and the ice caves."
    },
    "postcard": {
      "narration": "One final card, for the folks back home.",
      "line": "Singapore was warm, bright, and full of good company. Wish you were here, or maybe just slightly jealous."
    }
  },
